import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第二十五卦 无妄 天雷无妄 乾上震下","description":"周易 - 第二十五卦 无妄 天雷无妄 乾上震下","frontmatter":{"title":"第二十五卦 无妄 天雷无妄 乾上震下","description":"周易 - 第二十五卦 无妄 天雷无妄 乾上震下"},"headers":[],"relativePath":"zh/classics/zhouyi/026.md","filePath":"zh/classics/zhouyi/026.md"}'),l={name:"zh/classics/zhouyi/026.md"};function t(s,a,n,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="无妄" tabindex="-1">无妄 <a class="header-anchor" href="#无妄" aria-label="Permalink to “无妄”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>元，亨，利，贞。其匪正有眚，不利有攸往。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>无妄，刚自外来，而为主於内。动而健，刚中而应，大亨以正，天之命也。其匪正有眚，不利有攸往。无妄之往，何之矣？天命不佑，行矣哉？</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>天下雷行，物与无妄；先王以茂对时，育万物。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>无妄，往吉。象曰：无妄 之往，得志也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>不耕获，不菑畲，则利有攸往。象曰：不耕获，未富也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>无妄之灾，或系之牛，行人之得，邑人之灾。象曰：行人得牛，邑人灾也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>可贞，无咎。象曰：可贞无咎，固有之也。 九五：无妄之疾，勿药有喜。象曰：无妄之药，不可试也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>无妄，行有眚，无攸利。象曰：无妄之行，穷之灾也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
